REPLACE INTO `preguntas` (`id_pregunta`, `id_materia`, `pregunta`, `imagen_url`, `estado`, `usada`, `creado_en`) VALUES (1,1,'1. Vectores. Una fuerza de 12 N actúa hacia el este y otra de 5 N hacia el oeste. ¿Cuál es la resultante?',NULL,1,0,'2026-10-06 22:00:04'),(2,1,'2. MRU. Un móvil recorre 180 m en 12 s con velocidad constante. ¿Cuál es su velocidad?',NULL,1,0,'2026-10-06 22:00:04'),(3,1,'3. Magnitudes. ¿A cuántos metros por segundo equivalen 54 km/h?',NULL,1,0,'2026-10-06 22:00:04'),(4,1,'4. Movimiento vertical. En el punto más alto de un lanzamiento vertical, la velocidad instantánea del objeto es:',NULL,1,0,'2026-10-06 22:00:04'),(5,1,'5. Magnitudes. ¿Cuántos metros equivalen a 2,75 km?',NULL,1,0,'2026-10-06 22:00:04'),(6,1,'6. MRUV. Un automóvil parte del reposo con aceleración de 3 m/s². ¿Qué velocidad alcanza en 4 s?',NULL,1,0,'2026-10-06 22:00:04'),(7,1,'7. Vectores. Una persona camina 6 m al norte y luego 8 m al este. ¿Cuál es el módulo de su desplazamiento?',NULL,1,0,'2026-10-06 22:00:04'),(8,1,'8. MRUV. La velocidad de un móvil cambia de 5 m/s a 17 m/s en 4 s. ¿Cuál es su aceleración?',NULL,1,0,'2026-10-06 22:00:04'),(9,1,'9. Caída libre. Se deja caer un objeto desde el reposo. Despreciando el aire, después de 2 s su velocidad es:',NULL,1,0,'2026-10-06 22:00:04'),(10,1,'10. MRU. La gráfica posición tiempo de un MRU es una línea recta. Su pendiente representa:',NULL,1,0,'2026-10-06 22:00:04'),(11,1,'11. Magnitudes. ¿Cuál es una magnitud fundamental del Sistema Internacional?',NULL,1,0,'2026-10-06 22:00:04'),(12,1,'12. Vectores. Dos vectores de 9 N tienen igual dirección y sentidos opuestos. Su resultante es:',NULL,1,0,'2026-10-06 22:00:04'),(13,1,'13. MRUV. Un móvil tiene v₀ = 4 m/s y a = 2 m/s². ¿Cuál es su velocidad a los 6 s?',NULL,1,0,'2026-10-06 22:00:04'),(14,1,'14. Vectores. ¿Cuál de las siguientes magnitudes es vectorial?',NULL,1,0,'2026-10-06 22:00:04'),(15,1,'15. Movimiento vertical. Una pelota se lanza hacia arriba. Mientras asciende, su velocidad:',NULL,1,0,'2026-10-06 22:00:04'),(16,1,'16. Magnitudes. ¿Cuántos segundos equivalen a 3,5 minutos?',NULL,1,0,'2026-10-06 22:00:04'),(17,1,'17. MRU. Un ciclista se desplaza a 7 m/s durante 40 s. ¿Qué distancia recorre?',NULL,1,0,'2026-10-06 22:00:04'),(18,1,'18. MRUV. Un vehículo reduce su velocidad de 25 m/s a 5 m/s en 4 s. ¿Cuál es su aceleración?',NULL,1,0,'2026-10-06 22:00:04'),(19,1,'19. Caída libre. En ausencia de resistencia del aire, dos objetos de distinta masa soltados desde la misma altura:',NULL,1,0,'2026-10-06 22:00:04'),(20,1,'20. MRU. Un bus viaja a 72 km/h durante 30 s. ¿Qué distancia recorre?',NULL,1,0,'2026-10-06 22:00:04'),(21,2,'21. Astrónomo y matemático alemán que formuló las tres leyes del movimiento planetario. ¿Quién fue?',NULL,1,0,'2026-10-06 22:00:04'),(22,2,'22. Científico italiano que estudió la caída libre y el movimiento de los cuerpos e impulsó el uso experimental de las matemáticas en la Física. ¿Quién fue?',NULL,1,0,'2026-10-06 22:00:04'),(23,2,'23. Físico y matemático inglés que formuló las tres leyes del movimiento y la ley de gravitación universal. ¿Quién fue?',NULL,1,0,'2026-10-06 22:00:04'),(24,2,'24. Físico británico que investigó los agujeros negros y la cosmología, y predijo que los agujeros negros pueden emitir radiación. ¿Quién fue?',NULL,1,0,'2026-10-06 22:00:04'),(25,2,'25. Físico nacido en Alemania que desarrolló las teorías de la relatividad y estableció la equivalencia entre masa y energía, E = mc². ¿Quién fue?',NULL,1,0,'2026-10-06 22:00:04'),(26,2,'26. Sistema estandarizado de unidades utilizado internacionalmente para expresar mediciones físicas. ¿Qué es?',NULL,1,0,'2026-10-06 22:00:04'),(27,2,'27. Movimiento en línea recta con velocidad constante y aceleración igual a cero. ¿Qué es?',NULL,1,0,'2026-10-06 22:00:04'),(28,2,'28. Movimiento de un cuerpo sometido únicamente a la gravedad, despreciando la resistencia del aire. ¿Qué es?',NULL,1,0,'2026-10-06 22:00:04'),(29,2,'29. Aceleración que experimentan los cuerpos por la atracción gravitatoria terrestre, cuyo valor aproximado cerca de la superficie es 9,8 m/s². ¿Qué es?',NULL,1,0,'2026-10-06 22:00:04'),(30,2,'30. Segmento orientado que representa una magnitud mediante módulo, dirección y sentido. ¿Qué es?',NULL,1,0,'2026-10-06 22:00:04'),(31,3,'31. Recorrido del robot. Un robot recorre 15 m al norte, 9 m al este, 7 m al sur y 3 m al oeste. Determine la distancia total, las componentes del desplazamiento, el módulo de la resultante y su dirección. Grafique el recorrido y el desplazamiento.',NULL,1,0,'2026-10-06 22:00:04'),(32,3,'32. Ángulo entre dos vectores. Dos vectores A y B tienen módulos de 5 u y 8 u. Su suma tiene módulo de 7 u. Determine el ángulo entre los vectores.',NULL,1,0,'2026-10-06 22:00:04'),(33,3,'33. Vectores con módulos en relación uno a dos. Los módulos de dos vectores están en la relación 1:2. El módulo de su suma es el triple del módulo del vector menor. Determine el ángulo entre ellos.',NULL,1,0,'2026-10-06 22:00:04'),(34,5,'1. Mencione tres aplicaciones del electromagnetismo en ingeniería.',NULL,1,0,'2026-10-06 22:00:04'),(35,5,'2. Mencione tres tecnologías basadas en principios físicos.',NULL,1,0,'2026-10-06 22:00:04'),(36,5,'3. Mencione tres unidades de tiempo.',NULL,1,0,'2026-10-06 22:00:04'),(37,5,'4. Mencione tres unidades de longitud.',NULL,1,0,'2026-10-06 22:00:04'),(38,5,'5. Mencione las tres características de un vector.',NULL,1,0,'2026-10-06 22:00:04'),(39,5,'6. Mencione tres ramas de la Física.',NULL,1,0,'2026-10-06 22:00:04'),(40,5,'7. Mencione tres instrumentos de medición física.',NULL,1,0,'2026-10-06 22:00:04'),(41,5,'8. Mencione tres ejemplos de movimiento circular.',NULL,1,0,'2026-10-06 22:00:04'),(42,5,'9. Mencione tres fenómenos relacionados con la luz.',NULL,1,0,'2026-10-06 22:00:04'),(43,5,'10. Mencione tres magnitudes fundamentales del Sistema Internacional.',NULL,1,0,'2026-10-06 22:00:04'),(44,5,'11. Mencione las unidades del SI para longitud, masa y tiempo, en ese orden.',NULL,1,0,'2026-10-06 22:00:05'),(45,5,'12. ¿Cuántos metros equivalen a 0,6 kilómetros?',NULL,1,0,'2026-10-06 22:00:05'),(46,5,'13. ¿Cuántos segundos hay en dos minutos y medio?',NULL,1,0,'2026-10-06 22:00:05'),(47,5,'14. Convierta 36 kilómetros por hora a metros por segundo.',NULL,1,0,'2026-10-06 22:00:05'),(48,5,'15. Convierta 5 metros por segundo a kilómetros por hora.',NULL,1,0,'2026-10-06 22:00:05'),(49,5,'16. Dos fuerzas actúan en el mismo sentido: una de 4 newtons y otra de 6 newtons. ¿Cuál es el módulo de la resultante?',NULL,1,0,'2026-10-06 22:00:05'),(50,5,'17. Un móvil regresa a su punto de partida después de recorrer 20 metros. ¿Cuánto vale su desplazamiento?',NULL,1,0,'2026-10-06 22:00:05'),(51,5,'18. Un móvil recorre 60 metros en 10 segundos con velocidad constante. ¿Cuál es su rapidez?',NULL,1,0,'2026-10-06 22:00:05'),(52,5,'19. Una pelota se lanza verticalmente hacia arriba. En el punto más alto, ¿cuánto vale su aceleración?',NULL,1,0,'2026-10-06 22:00:05'),(53,5,'20. En el vacío, se sueltan simultáneamente una pluma y una piedra desde la misma altura. ¿Cuál llega primero al suelo?',NULL,1,0,'2026-10-06 22:00:05'),(54,5,'21. ¿Quién desarrolló las teorías de la relatividad especial y general?',NULL,1,0,'2026-10-06 22:00:05'),(55,5,'22. ¿Qué científica recibió premios Nobel en Física y en Química por investigaciones relacionadas con la radiactividad?',NULL,1,0,'2026-10-06 22:00:05'),(56,5,'23. ¿Qué físico predijo que los agujeros negros pueden emitir radiación debido a efectos cuánticos?',NULL,1,0,'2026-10-06 22:00:05'),(57,5,'24. ¿Cómo se llama el primer satélite paraguayo?',NULL,1,0,'2026-10-06 22:00:05'),(58,5,'25. ¿Qué forma de energía del agua almacenada aprovecha inicialmente Itaipú para generar electricidad?',NULL,1,0,'2026-10-06 22:00:05'),(59,5,'26. ¿Qué científico formuló la ley de elasticidad según la cual la deformación de un resorte es proporcional a la fuerza aplicada, dentro de su límite elástico?',NULL,1,0,'2026-10-06 22:00:05'),(60,5,'27. ¿Cuál es la unidad de energía y trabajo en el Sistema Internacional?',NULL,1,0,'2026-10-06 22:00:05'),(61,5,'28. ¿Qué instrumento se utiliza para medir la temperatura?',NULL,1,0,'2026-10-06 22:00:05'),(62,5,'29. ¿Qué instrumento permite medir la presión atmosférica?',NULL,1,0,'2026-10-06 22:00:05'),(63,5,'30. ¿Qué científico inventó la pila voltaica?',NULL,1,0,'2026-10-06 22:00:05'),(64,5,'31. ¿Qué instrumento permite observar objetos muy pequeños mediante lentes?',NULL,1,0,'2026-10-06 22:00:05'),(65,5,'32. ¿Qué instrumento indica direcciones mediante una aguja que responde al campo magnético terrestre?',NULL,1,0,'2026-10-06 22:00:05'),(66,5,'33. ¿Qué invento permite detectar objetos mediante ondas de radio y sus ecos?',NULL,1,0,'2026-10-06 22:00:05'),(67,5,'34. ¿Qué aparato transforma señales eléctricas en sonido audible?',NULL,1,0,'2026-10-06 22:00:05'),(68,5,'35. ¿Qué tecnología transporta señales luminosas por filamentos transparentes?',NULL,1,0,'2026-10-06 22:00:05');
